<?php require_once __DIR__.'/includes/auth.php'; if(empty($_SESSION['citizen_id'])) redirect('index.php');$phone=$_SESSION['citizen_phone'];$message='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pid=(int)($_POST['property_id']??0);$type=$_POST['service_type']??'';$details=trim($_POST['details']??'');$q=db()->prepare("SELECT p.id FROM properties p JOIN allottees a ON a.property_id=p.id WHERE p.id=? AND REPLACE(REPLACE(a.mobile,'+91',''),' ','')=? LIMIT 1");$q->execute([$pid,$phone]);if($q->fetch()&&in_array($type,['Mutation','KYC Update'],true)){$ref='LDA-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=db()->prepare('INSERT INTO citizen_requests(reference_no,citizen_id,property_id,service_type,details) VALUES(?,?,?,?,?)');$s->execute([$ref,$_SESSION['citizen_id'],$pid,$type,$details]);$message='Request submitted. Reference number: '.$ref;}else{$message='That property is not linked to your verified mobile number.';}}$s=db()->prepare("SELECT p.*,a.allottee_name,a.father_name,a.mobile,a.aadhar_no,a.pan_no FROM properties p JOIN allottees a ON a.property_id=p.id WHERE REPLACE(REPLACE(a.mobile,'+91',''),' ','')=? ORDER BY p.created_at DESC");$s->execute([$phone]);$properties=$s->fetchAll();$s=db()->prepare('SELECT r.*,p.property_code FROM citizen_requests r JOIN properties p ON p.id=r.property_id WHERE r.citizen_id=? ORDER BY r.submitted_at DESC');$s->execute([$_SESSION['citizen_id']]);$requests=$s->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Citizen Portal</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="dashboard-header"><div class="inner"><strong>LDA Citizen Portal</strong><span><?=e($_SESSION['citizen_name'])?> · <a class="back" href="citizen-logout.php">Logout</a></span></div></header><main class="dashboard-main"><a class="btn btn-outline" href="index.php">← Back to Home</a><div class="section-head" style="margin-top:28px"><div><div class="eyebrow">Verified mobile: <?=e($phone)?></div><h1>My properties</h1></div></div><?php if($message):?><div class="alert"><?=e($message)?></div><?php endif;?><?php if(!$properties):?><div class="notice"><h3>No linked properties found</h3><p class="muted">Your verified number does not match an allottee record yet.</p></div><?php endif;?><div class="two-col"><?php foreach($properties as $p):?><article class="portal-card"><span class="badge"><?=e($p['status'])?></span><h2><?=e($p['scheme_name'])?></h2><p><strong><?=e($p['property_no'])?></strong> · <?=e($p['property_code'])?><br><?=e($p['address'])?></p><p class="muted">Allottee: <?=e($p['allottee_name'])?><br>KYC: <?=($p['aadhar_no']&&$p['pan_no'])?'Complete':'Pending'?></p><button class="btn btn-primary" onclick="openService(<?=((int)$p['id'])?>)">Apply Service</button></article><?php endforeach;?></div><section class="section"><div class="eyebrow">Your activity</div><h2>My Applications</h2><div class="table-wrap"><table class="table"><tr><th>Reference</th><th>Property</th><th>Service</th><th>Status</th><th>Submitted</th></tr><?php foreach($requests as $r):?><tr><td><?=e($r['reference_no'])?></td><td><?=e($r['property_code'])?></td><td><?=e($r['service_type'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?=e($r['submitted_at'])?></td></tr><?php endforeach;?></table></div></section></main><div class="modal" id="serviceModal" hidden><div class="modal-dialog"><div class="form-card"><button class="modal-close" onclick="document.querySelector('#serviceModal').hidden=true">×</button><h2>Apply for a service</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="property_id" id="propertyId"><label class="form-label">Service</label><select class="form-select" name="service_type" required><option>Mutation</option><option>KYC Update</option></select><label class="form-label">Details</label><textarea name="details" rows="5" required></textarea><button class="btn btn-primary" style="margin-top:18px">Submit request</button></form></div></div></div><script>function openService(id){document.querySelector('#propertyId').value=id;document.querySelector('#serviceModal').hidden=false}</script></body></html>